{
    "room_version": "org.matrix.msc3787",
    "predecessor": {
        "room_id": "!FFDoPrcpeoLvVNcbmo:localhost",
        "event_id": "$RqUrDYxf9LIklWsLelCnyFd-Qq95LXB0gXlUfgUwPEw"
    },
